/*
 * A193666  F(2) odd Fib. numbers, F(3) even Fib. numbers, F(4) odd Fib.
 *          numbers..., F(n) = A000045(n), a(n) < a(n+1).
 * https://oeis.org/A193666
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = nth term of A193666. The sequence is generated by *
 *            iterating over the Fibonacci numbers F(i). For each block index
 *            k * starting at 2, take F(k) terms of the parity opposite to k:
 *            * if k is even → next F(k) odd Fibonacci numbers, * if k is odd
 *            → next F(k) even Fibonacci numbers. * The bloc...
 * Range:     u8 n <= 7, u16 n <= 11, u32 n <= 23, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Helpers:   fib_num
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/fib_num.h"

seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* offset starts at 1 */

    idx_t  count    = 0;              /* produced terms so far */
    idx_t  i        = 1;              /* current Fibonacci index (1‑based) */
    seq_t  prev = 0, cur = 1;         /* F(i-1), F(i) */

    idx_t  g        = 2;              /* current block index */
    idx_t  block_len   = (idx_t)fib_num(g);
    bool   take_odd    = (g % 2 == 0);   /* even k → odd fibs */
    idx_t  remaining   = block_len;

    while (true) {
        /* parity of F(i) is even iff i % 3 == 0 */
        bool selected = take_odd ? (i % 3 != 0) : (i % 3 == 0);
        if (selected) {
            ++count;
            if (count == n)
                return cur;

            --remaining;
            if (remaining == 0) {           /* start next block */
                ++g;
                take_odd   = (g % 2 == 0);
                block_len  = (idx_t)fib_num(g);
                remaining  = block_len;
            }
        }

        /* advance to next Fibonacci number */
        seq_t next = prev + cur;
        prev = cur;
        cur  = next;
        ++i;
    }
}
